// Per-portal listing-URL extraction from alert e-mails. Formats are unknown until real
// alerts arrive: extract every href, unwrap tracking redirects, match portal detail-URL
// patterns. Anything that yields zero listings is emitted as __unparsed for the ntfy branch.
const PORTALS = [
  { key: 'homegate', from: /homegate/i, pat: [/https?:\/\/(?:www\.)?homegate\.ch\/[a-z-]*(?:rent|louer|mieten)[^\s"'<>]*?\/(\d{6,})/gi] },
  { key: 'immoscout24', from: /immoscout24|immo-scout/i, pat: [/https?:\/\/(?:www\.)?immoscout24\.ch\/[^\s"'<>]*?\/(\d{6,})/gi, /https?:\/\/(?:www\.)?immoscout24\.ch\/(?:en|fr|de)?\/?d\/[^\s"'<>]*?-(\d{6,})/gi] },
  { key: 'newhome', from: /newhome/i, pat: [/https?:\/\/(?:www\.)?newhome\.ch\/[^\s"'<>]*?\/(\d{5,})[^\s"'<>]*/gi] },
  { key: 'comparis', from: /comparis/i, pat: [/https?:\/\/(?:en|fr|de|www)\.comparis\.ch\/immobilien\/[^\s"'<>]*?(?:show|details?)\/(\d{5,})/gi] },
  { key: 'petitesannonces', from: /petitesannonces/i, pat: [/https?:\/\/(?:www\.)?petitesannonces\.ch\/[^\s"'<>]*?[-\/](\d{5,})[^\s"'<>]*/gi] },
];
const hash = s => { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0; return h.toString(36); };
// n8n's IMAP "simple" format decodes bodies as latin-1 regardless of charset → UTF-8
// bodies arrive as mojibake (pièces→piÃ¨ces, m²→mÂ²). Reverse it when detected.
const fixMojibake = s => {
  if (!/[ÃÂ]./.test(s)) return s;
  try { return decodeURIComponent(escape(s)); } catch (e) { return s; }
};
const out = [];

// Comparis alerts (verified format 2026-07-18): opaque dispatcher/go?cgid= links (tracking,
// per-e-mail) + structured text cards. Parse cards from textPlain; source_id = content hash
// so the same flat in later alert e-mails (new cgid) still dedupes.
function parseComparis(j) {
  const text = String(j.textPlain ?? '');
  const items = [];
  const seenIds = new Set();
  const blocks = text.split(/<(https:\/\/[a-z]{2}\.comparis\.ch\/comparis\/dispatcher\/go\?cgid=[^>]+)>/);
  for (let i = 1; i < blocks.length; i += 2) {
    const link = blocks[i];
    const seg = blocks[i + 1] || '';
    const lines = seg.split('\n').map(l => l.trim()).filter(Boolean);
    if (!lines.length) continue;
    const title = lines[0];
    if (/^(contacter|modifier|supprimer|voir|version)/i.test(title) || /^<?https?:/i.test(title)) continue;
    const rentM = seg.match(/CHF\s*([\d']+)/);
    const addrM = seg.match(/^\s*(.+?)\s*\|\s*(\d{4})\s+([A-Za-zÀ-ž' .-]+?)\s*$/m);
    const rmM = seg.match(/(\d+(?:\.\d)?)\s*pi[eè]ces?\s*\|\s*(\d+)\s*m²/i);
    if (!rentM || !rmM) continue;
    const rent = rentM ? parseInt(rentM[1].replace(/'/g, ''), 10) : null;
    const gross = /inkl|compris|charges? incl/i.test(title);
    const rooms = rmM ? parseFloat(rmM[1]) : null;
    const addr = addrM ? addrM[1] : null;
    const commune = addrM ? addrM[3].trim() : null;
    const id = hash(['comparis', addr, rooms, rent].join('|'));
    if (seenIds.has(id)) continue;
    seenIds.add(id);
    items.push({ json: {
      source: 'email-comparis',
      source_id: id,
      url: link,
      title: title + (addr ? ' — ' + addr + (commune ? ', ' + commune : '') : ''),
      rent_net: gross ? null : rent, rent_gross: gross ? rent : null, charges: null,
      rooms, m2: rmM ? parseInt(rmM[2], 10) : null,
      commune, address_raw: addr,
      description: title, cross_key: null,
      published_at: j.date ? new Date(j.date).toISOString() : null,
      images: []
    }});
  }
  return items;
}

// immoscout24 + homegate are SMG portals sharing one alert template (plain text):
//   <sendgrid click link> / "<street N>, <NPA> <commune>" / "<m2> m2" / "<rooms> pièces"
//   / "CHF <rent>.–". Detail pages are DataDome-walled; APPT 21 enriches via the
//   replayed cookie. Both portals wrap the listing link in SendGrid (immoscout since
//   2026-07; a direct /louer/<id> link is still preferred when present). source_id =
//   portal initial + spec hash so a re-alert for the same flat dedupes.
function parseSmg(j, portalKey) {
  const text = String(j.textPlain || '');
  // match the listing's own spec lines (standalone "65 m2" / "3 pièces"), NOT the
  // search-criteria header line "Bulle, rent, 2.5–3.5 pièces".
  const m2m = text.match(/^[ \t]*(\d+)[ \t]*m2[ \t]*$/m);
  const rm = text.match(/^[ \t]*(\d+(?:[.,]\d)?)[ \t]*pi[eè]ces?[ \t]*$/m);
  const rooms = rm ? parseFloat(rm[1].replace(',', '.')) : null;
  const m2 = m2m ? parseInt(m2m[1], 10) : null;
  // "Impasse des Erables 9, 1635 La Tour-de-Trême" — street part may contain digits;
  // the criteria header has no ", NPA commune" tail so it cannot match.
  const addrM = text.match(/^\s*(.+?),\s*(\d{4})\s+([A-Za-zÀ-ÿ'.\- ]+?)\s*$/m);
  const street = addrM ? addrM[1].trim() : null;
  const commune = addrM ? addrM[3].trim() : null;
  // portal search results advertise the gross rent ("CHF 1'128.–"); enrichment
  // overwrites with the detail page's authoritative net/gross split.
  const rentM = text.match(/CHF\s*([\d'’]+)/);
  const rent = rentM ? parseInt(rentM[1].replace(/['’]/g, ''), 10) : null;
  let url = null, id = null;
  const direct = text.match(/https?:\/\/www\.immoscout24\.ch\/louer\/(\d+)/);
  if (portalKey === 'immoscout24' && direct) {
    id = direct[1]; url = 'https://www.immoscout24.ch/louer/' + id;
  } else {
    // first SendGrid click link in the body is the listing (promo/unsubscribe follow)
    const um = text.match(/https:\/\/[a-z0-9.]*sendgrid\.net\/ls\/click\?[^\s"'<>]+/i);
    if (um) url = um[0];
    id = portalKey.charAt(0) + hash([commune, street, rooms, m2].join('|'));
  }
  if (!rooms || (!id && !url)) return null;
  if (!id) id = 'u' + hash(url || '');
  return [{ json: {
    source: 'email-' + portalKey,
    source_id: id,
    url,
    title: (rooms ? rooms + ' pièces' : 'Appartement') + (m2 ? ' · ' + m2 + ' m²' : '') +
           (commune ? ' — ' + commune : '') + ' (' + portalKey + ')',
    rent_net: null, rent_gross: rent, charges: null,
    rooms, m2, commune,
    address_raw: street ? street + (commune ? ', ' + commune : '') : null,
    description: '', cross_key: null,
    published_at: j.date ? new Date(j.date).toISOString() : null,
    images: []
  }}];
}

for (const item of $input.all()) {
  let j = item.json;
  const from = String(j.from ?? '');
  const subject = String(j.subject ?? '(sans sujet)');
  const bodyHtml = fixMojibake(String(j.textHtml ?? ''));
  const bodyText = fixMojibake(String(j.textPlain ?? ''));
  j = { ...j, textHtml: bodyHtml, textPlain: bodyText };
  const body = bodyHtml || bodyText;
  const portal = PORTALS.find(p => p.from.test(from)) || PORTALS.find(p => p.from.test(body.slice(0, 2000)));
  if (portal && portal.key === 'comparis') {
    const items = parseComparis(j);
    if (items.length) { out.push(...items); continue; }
    out.push({ json: { __unparsed: true, from, subject, portal: 'comparis',
      snippet: (bodyText || bodyHtml).replace(/\s+/g, ' ').slice(0, 300) } });
    continue;
  }
  if (portal && (portal.key === 'immoscout24' || portal.key === 'homegate')) {
    const items = parseSmg(j, portal.key);
    if (items && items.length) { out.push(...items); continue; }
    out.push({ json: { __unparsed: true, from, subject, portal: portal.key,
      snippet: (bodyText || bodyHtml).replace(/\s+/g, ' ').slice(0, 300) } });
    continue;
  }
  // collect candidate URLs: raw hrefs + redirect-unwrapped variants
  const candidates = new Set();
  for (const m of body.matchAll(/href="([^"]+)"/gi)) candidates.add(m[1]);
  for (const m of body.matchAll(/https?:\/\/[^\s"'<>]+/gi)) candidates.add(m[0]);
  for (const c of [...candidates]) {
    for (const pm of c.matchAll(/[?&](?:url|u|link|redirect|target|dest)=([^&]+)/gi)) {
      try { candidates.add(decodeURIComponent(pm[1])); } catch (e) { /* skip bad encoding */ }
    }
    if (/&amp;/.test(c)) candidates.add(c.replace(/&amp;/g, '&'));
  }
  const found = new Map();
  if (portal) {
    for (const cand of candidates) {
      for (const pat of portal.pat) {
        for (const m of cand.matchAll(pat)) {
          const id = m[1] || hash(m[0]);
          if (!found.has(id)) found.set(id, m[0]);
        }
      }
    }
  }
  if (!portal || found.size === 0) {
    out.push({ json: { __unparsed: true, from, subject, portal: portal ? portal.key : 'unknown',
      snippet: (bodyText || bodyHtml).replace(/\s+/g, ' ').slice(0, 300) } });
    continue;
  }
  const desc = bodyText.replace(/\s+/g, ' ').trim().slice(0, 900);
  for (const [id, url] of found) {
    out.push({ json: {
      source: 'email-' + portal.key,
      source_id: id,
      url: url.split('?')[0],
      title: subject + ' (' + portal.key + ')',
      rent_net: null, rent_gross: null, charges: null, rooms: null, m2: null,
      commune: null, address_raw: null,
      description: desc, cross_key: null,
      published_at: j.date ? new Date(j.date).toISOString() : null,
      images: []
    }});
  }
}
return out;
